// ConsentVault receiver step 1: check the signature over the exact body bytes, then read the message.
// FILL IN: ONE key (shown in the portal when you connect the system), and your CRM field names.
const HMAC_SECRET_HEX = `PASTE_HMAC_SECRET_HERE`;            // 64 hex characters, shown once
// Paste the whole key, line breaks included, between the backticks (it is shown in the portal after you connect).
const ED25519_PUBLIC_KEY_PEM = `PASTE_ED25519_PUBLIC_KEY_HERE`;
// One CRM field per channel (calls, texts, email). Each field also gets a "_version" companion field that holds the last version applied.
const CHANNEL_FIELDS = { voice: 'consentvault_calls', artificial_voice: 'consentvault_prerecorded_calls', sms: 'consentvault_texts', email: 'consentvault_email' };
// Only if your CRM has nothing finer: ONE blanket do-not-contact field. Leave empty to refuse a channel with no field of its own. Stops only; a grant never lifts it.
const BLANKET_FIELD = '';

const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const body = await this.helpers.getBinaryDataBuffer(0, 'data');
const header = String(headers['x-consentvault-signature'] || '');
const fail = (reason) => [{ json: { valid: false, reason } }];
const unset = (v) => !v || v.startsWith('PASTE_');

let ok = false;
if (header.startsWith('hmac-sha256=')) {
  if (unset(HMAC_SECRET_HEX)) return fail('the message is signed with a shared secret but no secret is filled in');
  const expected = crypto.createHmac('sha256', Buffer.from(HMAC_SECRET_HEX, 'hex')).update(body).digest();
  const given = Buffer.from(header.slice('hmac-sha256='.length), 'hex');
  ok = given.length === expected.length && crypto.timingSafeEqual(given, expected);
} else if (header.startsWith('ed25519=')) {
  if (unset(ED25519_PUBLIC_KEY_PEM)) return fail('the message is signed with a key pair but no public key is filled in');
  try {
    ok = crypto.verify(null, body, crypto.createPublicKey(ED25519_PUBLIC_KEY_PEM), Buffer.from(header.slice('ed25519='.length), 'hex'));
  } catch (e) { ok = false; }
} else {
  return fail('no signature header on the message');
}
if (!ok) return fail('the signature does not match the body');

let msg;
try { msg = JSON.parse(body.toString('utf8')); } catch (e) { return fail('the body is not JSON'); }
if (msg.test === true) return [{ json: { valid: true, isTest: true } }];

// Duplicate delivery: the same Idempotency-Key was already applied (it is remembered only after a successful run).
const idemKey = String(headers['idempotency-key'] || '');
const seen = ($getWorkflowStaticData('global').seenKeys) || [];
const duplicate = idemKey !== '' && seen.includes(idemKey);

// Matching: email lowercased, phone as E.164 (a 10 digit number is taken as US).
const raw = String(msg.contact || '').trim();
let contactKind = 'fingerprint', value = raw;
if (raw.includes('@')) { contactKind = 'email'; value = raw.toLowerCase(); }
else if (/^[+(]?[0-9][0-9 ()\-.]{6,}$/.test(raw)) {
  const digits = raw.replace(/[^0-9]/g, '');
  contactKind = 'phone';
  value = raw.startsWith('+') ? '+' + digits : digits.length === 10 ? '+1' + digits : digits.length === 11 && digits.startsWith('1') ? '+' + digits : '+' + digits;
}

const own = CHANNEL_FIELDS[msg.channel];
const stateField = own || BLANKET_FIELD;
const useBlanket = !own && !!BLANKET_FIELD;
let refuse = '';
if (contactKind === 'fingerprint') refuse = 'This system is set to Fingerprint only, so a CRM contact cannot be matched. In ConsentVault, connect it with Contact sent as: Plain contact point.';
else if (!stateField) refuse = 'No CRM field is mapped for the channel ' + msg.channel + '. Add it to CHANNEL_FIELDS or set BLANKET_FIELD.';
else if (msg.channel_state === undefined || msg.channel_version === undefined) refuse = 'The message has no channel_state or channel_version, so a stop on another purpose cannot be told apart. Ask ConsentVault to send it again after the update.';

return [{ json: {
  valid: true, isTest: false, duplicate, refuse, idemKey, contactKind, contact: value,
  searchProperty: contactKind === 'email' ? 'email|string' : 'phone|string',
  channel: msg.channel, purpose: msg.purpose, state: msg.state, version: Number(msg.version),
  channelState: msg.channel_state, channelVersion: Number(msg.channel_version),
  basisEventId: msg.basis_event_id, at: msg.at, reason: msg.reason,
  stateField, versionField: stateField + '_version', useBlanket,
} }];

// ConsentVault receiver step 2: decide what to do with the contacts the CRM search returned. Never creates a contact.
// The channel's state is denied while ANY purpose on the channel is denied (channel_state), so a grant for one purpose can never lift a stop on another.
// A denied channel is always applied, whatever the stored version. The channel version (the sum of the channel's purpose versions, never decreasing) gates grants only.
const p = $('Verify signature').first().json;
const found = $input.all().map((i) => i.json).filter((j) => j && j.id);
if (found.length === 0) return [{ json: { action: 'nomatch', state: p.state, channel: p.channel, contact: p.contact } }];
if (p.useBlanket && p.channelState !== 'denied') return [{ json: { action: 'logged', note: 'a grant never lifts the blanket field' } }];
// The n8n HubSpot search returns each contact as { id, properties: { name: 'plain string' } }.
const stored = (c) => Number((c.properties || {})[p.versionField] ?? 0);
// A grant matched on a phone is applied only when the contact holds no other phone number than the one matched (a stop on another number
// of the same person must not be cleared). Stops always apply.
const e164 = (v) => { const s = String(v || '').trim(); const d = s.replace(/[^0-9]/g, ''); return !d ? '' : s.startsWith('+') ? '+' + d : d.length === 10 ? '+1' + d : '+' + d; };
const holdsAnotherNumber = (c) => p.contactKind === 'phone' && ['phone', 'mobilephone'].map((f) => e164((c.properties || {})[f])).some((n) => n && n !== p.contact);
const todo = found.filter((c) => p.channelState === 'denied' || (stored(c) < p.channelVersion && !holdsAnotherNumber(c)));
if (todo.length === 0 && found.some(holdsAnotherNumber)) return [{ json: { action: 'held', note: 'a grant was not applied: the contact holds another phone number, so it is left as it is' } }];
if (todo.length === 0) return [{ json: { action: 'stale', note: 'every matching contact already holds this version or a newer one' } }];
return todo.map((c) => ({ json: { action: 'update', id: c.id, properties: {
  [p.stateField]: p.channelState,
  [p.versionField]: String(Math.max(stored(c), p.channelVersion)),
  consentvault_changed_at: p.at,
} } }));

const d = $('Decide').first().json;
console.log('ConsentVault: ' + (d.action === 'nomatch' ? 'not in CRM, add by hand. ' : d.action + '. ') + JSON.stringify({ channel: d.channel, state: d.state, note: d.note }));
return [{ json: { result: d.action } }];

// Remember the delivery only after the CRM work finished, so a failed run is retried and a finished one is not repeated.
const key = $('Verify signature').first().json.idemKey;
if (key) {
  const data = $getWorkflowStaticData('global');
  data.seenKeys = [...(data.seenKeys || []), key].slice(-500);
}
return [{ json: { remembered: !!key } }];
